				OutputTokens: 200,
			},
			FilesTouched: []string{"file1.go", "file2.go"},
		},
		Transcript: []byte(`{"type":"text","content":"test"}`),
		Prompts:    "Test prompt",
		Context:    []byte("Test context"),
