{"type":"assistant","uuid":"a1","message":{"content":[{"type":"text","text":"First response"}]}}
{"type":"user","uuid":"u2","message":{"content":"Second prompt - SHOULD appear"}}
{"type":"assistant","uuid":"a2","message":{"content":[{"type":"text","text":"Second response"}]}}
`)

